import ast
import operator

_ALLOWED_BIN_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
}

_ALLOWED_UNARY_OPS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
    ast.Not: operator.not_,
}

_ALLOWED_COMPARE_OPS = {
    ast.Eq: operator.eq,
    ast.NotEq: operator.ne,
    ast.Lt: operator.lt,
    ast.LtE: operator.le,
    ast.Gt: operator.gt,
    ast.GtE: operator.ge,
    ast.Is: operator.is_,
    ast.IsNot: operator.is_not,
    ast.In: lambda left, right: left in right,
    ast.NotIn: lambda left, right: left not in right,
}

def _safe_eval_node(node):
    if isinstance(node, ast.Expression):
        return _safe_eval_node(node.body)

    if isinstance(node, ast.Constant):
        return node.value

    if isinstance(node, ast.Tuple):
        return tuple(_safe_eval_node(element) for element in node.elts)

    if isinstance(node, ast.List):
        return [_safe_eval_node(element) for element in node.elts]

    if isinstance(node, ast.Set):
        return {_safe_eval_node(element) for element in node.elts}

    if isinstance(node, ast.Dict):
        return {
            _safe_eval_node(key): _safe_eval_node(value)
            for key, value in zip(node.keys, node.values)
        }

    if isinstance(node, ast.BinOp):
        op_func = _ALLOWED_BIN_OPS.get(type(node.op))
        if op_func is None:
            raise ValueError('Unsupported or unsafe operator')
        return op_func(_safe_eval_node(node.left), _safe_eval_node(node.right))

    if isinstance(node, ast.UnaryOp):
        op_func = _ALLOWED_UNARY_OPS.get(type(node.op))
        if op_func is None:
            raise ValueError('Unsupported or unsafe operator')
        return op_func(_safe_eval_node(node.operand))

    if isinstance(node, ast.BoolOp):
        if isinstance(node.op, ast.And):
            result = True
            for value in node.values:
                result = _safe_eval_node(value)
                if not result:
                    return result
            return result

        if isinstance(node.op, ast.Or):
            result = False
            for value in node.values:
                result = _safe_eval_node(value)
                if result:
                    return result
            return result

        raise ValueError('Unsupported or unsafe boolean operator')

    if isinstance(node, ast.Compare):
        left = _safe_eval_node(node.left)
        for op, comparator in zip(node.ops, node.comparators):
            right = _safe_eval_node(comparator)
            op_func = _ALLOWED_COMPARE_OPS.get(type(op))
            if op_func is None:
                raise ValueError('Unsupported or unsafe comparison operator')
            if not op_func(left, right):
                return False
            left = right
        return True

    if isinstance(node, ast.IfExp):
        return _safe_eval_node(node.body if _safe_eval_node(node.test) else node.orelse)

    raise ValueError('Unsupported or unsafe expression')

def evalInput(inputStr):
    '''
    Run the inputStr as a safe Python expression and return the result of the computed expression.
    '''
    parsed = ast.parse(inputStr, mode='eval')
    output = _safe_eval_node(parsed)
    return output

