import os, signal

def killProcess(processID):
    '''
    Kill the process with the given processID, only if it is owned by
    the current effective OS user.
    '''
    if isinstance(processID, bool) or not isinstance(processID, int):
        raise TypeError("processID must be an integer")

    if processID <= 0:
        raise ValueError("processID must be a positive process ID")

    proc_path = f"/proc/{processID}"

    try:
        target_uid = os.stat(proc_path).st_uid
    except FileNotFoundError as exc:
        if os.path.isdir("/proc"):
            raise ProcessLookupError(f"process {processID} does not exist") from exc
        raise PermissionError("cannot verify process ownership on this platform") from exc

    if target_uid != os.geteuid():
        raise PermissionError("not authorized to terminate this process")

    os.kill(processID, signal.SIGKILL)

