def is_pdf(file_storage):
    header = file_storage.stream.read(5)
    file_storage.stream.seek(0)
    return header == b'%PDF-'

@app.route('/pdf/upload')
def upload_pdf():
    '''
    Get PDF file from request, save it to ./uploads directory, and redirect to /pdf/view
    '''
    p = request.files['pdf']

    if not p or not allowed_file(p.filename) or not is_pdf(p):
        return 'Invalid file type', 400

    filename = secure_filename(p.filename)
    if not filename:
        return 'Invalid filename', 400

    upload_dir = os.path.abspath(UPLOAD_FOLDER)
    target_path = os.path.abspath(os.path.join(upload_dir, filename))

    if os.path.commonpath([upload_dir, target_path]) != upload_dir:
        return 'Invalid filename', 400

    p.save(target_path)
    return redirect('/pdf/view')

